-- ============================================================
-- RPC criar_pedido_com_estoque: grava subtotal (não mais total, que agora é
-- gerado) e o pedido nasce em 'aguardando_cotacao_frete'. Mantém os guards
-- de autorização das migrations 005/006 e a baixa atômica de estoque da 004.
-- ============================================================

DROP FUNCTION IF EXISTS criar_pedido_com_estoque(UUID, UUID, forma_pagamento, JSONB, JSONB);

CREATE FUNCTION criar_pedido_com_estoque(
  p_pedido_id        UUID,
  p_cliente_id       UUID,
  p_forma_pagamento  forma_pagamento,
  p_endereco_entrega JSONB,
  p_itens            JSONB
)
RETURNS TABLE (pedido_id UUID, subtotal NUMERIC)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_item            JSONB;
  v_produto_id      UUID;
  v_quantidade      INTEGER;
  v_preco_unitario  NUMERIC;
  v_total           NUMERIC := 0;
  v_linhas_afetadas INTEGER;
BEGIN
  IF auth.uid() IS NULL OR p_cliente_id <> auth.uid() THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '28000';
  END IF;

  IF jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'CARRINHO_VAZIO' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO pedidos (id, cliente_id, status, subtotal, forma_pagamento, endereco_entrega)
  VALUES (p_pedido_id, p_cliente_id, 'aguardando_cotacao_frete', 0, p_forma_pagamento, p_endereco_entrega);

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
  LOOP
    v_produto_id := (v_item->>'produto_id')::UUID;
    v_quantidade := (v_item->>'quantidade')::INTEGER;

    IF v_quantidade IS NULL OR v_quantidade <= 0 THEN
      RAISE EXCEPTION 'QUANTIDADE_INVALIDA: %', v_produto_id USING ERRCODE = 'P0001';
    END IF;

    UPDATE produtos
    SET estoque = estoque - v_quantidade
    WHERE id = v_produto_id AND status = 'publicado' AND estoque >= v_quantidade
    RETURNING preco_site INTO v_preco_unitario;

    GET DIAGNOSTICS v_linhas_afetadas = ROW_COUNT;

    IF v_linhas_afetadas = 0 OR v_preco_unitario IS NULL THEN
      RAISE EXCEPTION 'ESTOQUE_INSUFICIENTE: %', v_produto_id USING ERRCODE = 'P0001';
    END IF;

    v_total := v_total + (v_preco_unitario * v_quantidade);

    INSERT INTO pedido_itens (pedido_id, produto_id, preco_unitario, quantidade)
    VALUES (p_pedido_id, v_produto_id, v_preco_unitario, v_quantidade);
  END LOOP;

  UPDATE pedidos SET subtotal = v_total WHERE id = p_pedido_id;

  RETURN QUERY SELECT p_pedido_id, v_total;
END;
$$;

GRANT EXECUTE ON FUNCTION criar_pedido_com_estoque(UUID, UUID, forma_pagamento, JSONB, JSONB) TO authenticated;

-- ============================================================
-- RPC estornar_pedido_estoque: agora também cancela pedidos ainda esperando
-- cotação de frete (antes só cobria aguardando_pagamento).
-- ============================================================

CREATE OR REPLACE FUNCTION estornar_pedido_estoque(
  p_pedido_id UUID
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_linhas_afetadas INTEGER;
  v_item            RECORD;
BEGIN
  UPDATE pedidos
  SET status = 'cancelado'
  WHERE id = p_pedido_id AND status IN ('aguardando_cotacao_frete', 'aguardando_pagamento');

  GET DIAGNOSTICS v_linhas_afetadas = ROW_COUNT;

  IF v_linhas_afetadas = 0 THEN
    RETURN;
  END IF;

  FOR v_item IN
    SELECT produto_id, quantidade FROM pedido_itens WHERE pedido_id = p_pedido_id
  LOOP
    UPDATE produtos
    SET estoque = estoque + v_item.quantidade
    WHERE id = v_item.produto_id;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION ajustar_centavos_identificacao_pedido()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_centavos_alvo     INTEGER;
  v_total_antes_cent  INTEGER;
  v_reais_base        INTEGER;
  v_centavos_atuais   INTEGER;
  v_reais_ajustados   INTEGER;
  v_total_depois_cent INTEGER;
  v_delta_cent        INTEGER;
BEGIN
  v_centavos_alvo := NEW.numero_pedido % 100;

  v_total_antes_cent := ROUND((NEW.subtotal + NEW.frete_valor) * 100)::INTEGER;
  v_reais_base := v_total_antes_cent / 100;
  v_centavos_atuais := v_total_antes_cent - v_reais_base * 100;

  IF v_centavos_alvo <= v_centavos_atuais THEN
    v_reais_ajustados := v_reais_base + 1;
  ELSE
    v_reais_ajustados := v_reais_base;
  END IF;

  v_total_depois_cent := v_reais_ajustados * 100 + v_centavos_alvo;
  v_delta_cent := v_total_depois_cent - v_total_antes_cent;

  IF NEW.frete_valor > 0 THEN
    NEW.frete_valor := NEW.frete_valor + (v_delta_cent / 100.0);
  ELSE
    NEW.subtotal := NEW.subtotal + (v_delta_cent / 100.0);
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ajustar_centavos_pedido ON pedidos;
CREATE TRIGGER trg_ajustar_centavos_pedido
  BEFORE UPDATE OF status ON pedidos
  FOR EACH ROW
  WHEN (NEW.status = 'aguardando_pagamento' AND OLD.status <> 'aguardando_pagamento')
  EXECUTE FUNCTION ajustar_centavos_identificacao_pedido();

